import sys
from sys import stdin

def compute_z(s):
    n = len(s)
    z = [0] * n
    z[0] = n
    l, r = 0, 0
    for i in range(1, n):
        if i < r:
            z[i] = min(r - i, z[i - l])
        while i + z[i] < n and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] > r:
            l, r = i, i + z[i]
    return z

def main():
    s = stdin.readline().strip()
    if not s:
        return
    n = len(s)
    z_full = compute_z(s)

    q_line = stdin.readline()
    if not q_line:
        return
    q = int(q_line)

    queries = []
    for _ in range(q):
        line = stdin.readline()
        while line and not line.strip():
            line = stdin.readline()
        if not line:
            break
        parts = list(map(int, line.split()))
        l, r = parts[0], parts[1]
        queries.append((l, r))

    results = []
    for l, r in queries:
        sub_len = r - l + 1
        total = 0
        idx_start = l - 1
        for i in range(sub_len):
            pos = idx_start + i
            val = z_full[pos]
            if val > sub_len - i:
                val = sub_len - i
            total += val
        results.append(total)

    print('\n'.join(map(str, results)))

if __name__ == "__main__":
    main()
